#!/usr/bin/env python3
import json

def a(href, text):
    return '<a href="%s" target="_blank" rel="noopener">%s</a>' % (href, text)
def p(html): return {'t': 'p', 'html': html}

CASE = 'https://case.edu/ech/articles/h/harris-corp'
WASH = 'https://www.washingtontechnology.com/2002/07/harris-team-wins-17-billion-faa-telecom-deal/320288/'
WIKI = 'https://en.wikipedia.org/wiki/L3Harris'
HIST = 'https://www.l3harris.com/company/our-history'
AERO = 'https://www.l3harris.com/newsroom/press-release/2023/07/l3harris-completes-aerojet-rocketdyne-acquisition'
MILE = 'https://www.l3harris.com/newsroom/editorial/2026/05/l3harris-reaches-over-50-faa-telecommunications-modernization'
DOT  = 'https://www.transportation.gov/briefing-room/icymi-us-transportation-secretary-sean-p-duffy-provides-update-restoration-airspace'
USAT = 'https://www.usatoday.com/story/news/nation/2026/11/14/faa-ground-stop-probe-l3harris/92780406007/'
FOX  = 'https://www.foxbusiness.com/fox-news-air-space/who-l3harris-federal-contractor-sec-duffy-says-may-have-caused-faa-outage'
GOV  = 'https://www.highergov.com/contract-opportunity/announcement-of-fti-single-source-extension-dtfa0102d03006-ssj-22-0001-u-9b1f3/'
STK  = 'https://stockanalysis.com/stocks/LHX/'

lr = {
 'title': 'The network America flies on',
 'fact': "A Slow Burn long read, Sunday 15 November 2026. On Friday afternoon America's aviation authority stopped every departure in the country for five hours; on Saturday the Transportation Secretary stood at a podium and named the cause: a single router, replaced during routine maintenance by the contractor that has run the air-traffic telephone network for twenty-four years. That contractor is L3Harris - a company built from a printing-press shop in 1895, a radio maker bought for army maps, a 1997 roll-up named for its two founders and a bank, and the 43-billion-dollar merger of equals that joined them in 2019. This is the build story: the sheet feeder, the satellites, the $1.7 billion contract nobody remembers bidding, and the Saturday press conference that put a 131-year-old name on the evening news.",
 'groups': []
}
G = lr['groups']

G.append({'heading': '1. The sheet feeder', 'blocks': [
 p(' The company that would one day connect every control tower in America began by speeding up paper. In the early 1890s, in Niles, Ohio, two brothers - Alfred and Charles G. Harris - built an automatic sheet feeder to end the laborious business of hand-feeding printing presses, and in 1895 they incorporated the Harris Automatic Press Company. The machine made old presses nearly ten times as productive, and the brothers rode it to the front of commercial printing: pioneers of offset lithography, a new factory on East 71st Street in Cleveland by 1917, a 1926 merger that made them Harris-Seybold-Potter, a four-color press in 1931 (' + a(CASE, 'the Encyclopedia of Cleveland History') + '). For half a century, Harris meant ink. The first crack in that identity came from the Army: in 1951 Harris built a portable, professional-quality press so the military could print multicolor maps and reconnaissance photos in the field - and a company that printed for generals began buying its way into electronics, picking up Gates Radio and a small defense research shop called Autronics.'),
 p(' The man who turned the crack into a doorway was George S. Dively, who took control in 1947 and spent two decades pushing the pressmaker into electronics. The decisive purchase came in 1967: Radiation, Incorporated, a Florida electronics firm wired into the young space program around Cape Canaveral, which gave Harris control technology for its typesetters and - far more valuable in hindsight - an entry into semiconductors and communication systems. By 1970 electronics supplied half of the company\'s $380 million in sales; that year Harris opened a plant in Melbourne, Florida, and in 1978 it moved the headquarters there, leaving Cleveland and, eventually, printing itself behind (' + a(CASE, 'Case Western\'s history') + '). The press company had become a radio-and-chip company. Its newest neighbor was the space coast - and its newest customer habit was the federal government.'),
]})

G.append({'heading': '2. The other company', 'blocks': [
 p(' The second parent was born a century later, in the deal debris of the 1990s defense industry. When Lockheed and Martin Marietta merged in 1993, they shed business units that had once belonged to Loral Corporation; in 1997 two Loral veterans - Frank Lanza and Robert LaPenta - teamed with Lehman Brothers to buy them, forming a company they named L-3 Communications. The letter-and-number was an acronym of the partners: Lanza, LaPenta and Lehman (' + a(WIKI, 'the corporate record') + '). Where Harris had grown by reinventing one company, L-3 grew by buying many: a roll-up of defense electronics, secure communications and surveillance businesses that made it one of the ten largest contractors to the United States government within a decade. By the end of 2016, the hyphenated startup label no longer fit a company of that size, and L-3 Communications renamed itself L3 Technologies.'),
 p(' The two bloodlines shared a city and a worldview. Both were headquartered in Melbourne, Florida. Both sold the unglamorous layer of defense - radios, sensors, networks - rather than the platforms that make magazine covers: L3Harris remains one of the largest suppliers of tactical radios to the American military (' + a(FOX, 'Fox Business\'s profile') + '). And both were mid-tier primes in a market that punished mid-tier primes, squeezed between the giants above and the specialists below. In October 2018 they announced the obvious answer to each other: an all-stock "merger of equals." Antitrust required one sacrifice - Harris sold its night-vision division, because combining the two companies\' night-vision businesses would have handed the merged firm an effective monopoly - and in June 2019 the deal closed: L3Harris Technologies, roughly $43 billion in combined value, the country\'s sixth-largest defense technology company at birth (' + a(USAT, 'USA Today\'s account') + '; ' + a(WIKI, 'the merger record') + '). Harris\'s Bill Brown took the chairman and chief executive titles; in June 2021 the chair passed to Chris Kubasik, who runs the company today.'),
]})

G.append({'heading': '3. The contract nobody saw', 'blocks': [
 p(' On 15 July 2002, Harris Corporation won the contract that defines this story, and almost nobody outside Washington noticed. The Federal Aviation Administration awarded Harris a fifteen-year, $1.7 billion deal to integrate and modernize the FAA Telecommunications Infrastructure - FTI - the nervous system that connects what were then more than 5,000 FAA facilities. Harris beat teams led by Lockheed Martin and by the incumbent, WorldCom, and promised to consolidate four legacy networks, replace more than 35,000 circuits, and run the whole thing as one managed service; the company expected the program\'s value to grow toward $3.5 billion by 2017, with a bench of subcontractors that read like the phone book - BellSouth, Qwest, SBC, Sprint and Verizon, with Raytheon on site support (' + a(WASH, 'Washington Technology\'s 2002 report') + '). The bet Harris made was unusual for a manufacturer: stop selling the FAA boxes, and start selling it the network itself - owned, operated and refreshed by the contractor, consumed by the government as a dial tone.'),
 p(' The network that contract bought is not an abstraction. FTI carries the voice calls between controllers and pilots, the radar feeds, the weather data, the flight plans - every mission-critical byte of the National Airspace System across two separate networks, one for air-traffic operations and one for the agency\'s back office, reaching more than 4,000 operational locations and about a thousand administrative ones, plus VPN access for more than 35,000 employees, in the continental United States and out to Alaska, Hawaii, Puerto Rico, Guam and international sites (' + a(GOV, 'the FAA\'s own contract description') + '). L3Harris says the system it operates and modernizes supports about 45,000 flights a day (' + a(USAT, 'USA Today') + '). When it works, it is invisible - which is precisely what the FAA paid for. The contract outlived its 2017 horizon and keeps getting extended: the company describes itself, accurately, as a legacy provider that has worked for the FAA for more than twenty years (' + a(FOX, 'Fox Business') + ').'),
]})

G.append({'heading': '4. The build-out', 'blocks': [
 p(' What L3Harris inherited in 2002, and still operates, is a network built on copper - time-division multiplexing, the same multiplexed-copper technology that ran the world\'s phone calls in the 1980s. Replacing it without ever stopping it is the company\'s defining engineering discipline, and its method has a name: build-then-switch. New fiber paths are installed beside the live copper, tested in parallel, and cut over only in carefully coordinated low-traffic windows, with full backup in place - "operations never stop in air traffic control, so neither do we," as Chris Collings, the vice president who runs the managed-services business, put it (' + a(MILE, 'L3Harris\'s account of the program') + '). The company was deploying 150 to 200 new network paths a month - dense urban centers, remote Alaskan sites, mountain tops - and hired about 200 telecommunications engineers in Melbourne plus a field force of more than 250 technicians, with 175 more positions planned for 2026.'),
 p(' In May this year the company announced it had passed 50 percent of the nationwide copper-to-fiber conversion, calling it proof that a safety-critical network can be rebuilt at speed "without disrupting the 45,000 daily flights that depend on it" (' + a(MILE, 'the milestone release') + '). By this weekend, the company said the figure stood above 70 percent (' + a(USAT, 'USA Today') + '). And the clock on the rest has been set from above: FAA Administrator Bryan Bedford wants the copper gone entirely by September 2027, and on Friday, with smoke still clearing, Transportation Secretary Sean Duffy raised the funding request for the whole air-traffic overhaul to $50 billion - "this is an emergency" - naming AT&T, Verizon and Lumen as the carriers of the next architecture (' + a(USAT, 'USA Today') + '; ' + a(FOX, 'Fox Business') + '). The modernization money is enormous, and it is aimed at replacing much of what L3Harris has spent two decades operating.'),
]})

G.append({'heading': '5. The fourth leg', 'blocks': [
 p(' While the network business ground through its copper, the merged company kept buying reach. The biggest move came in December 2022, when L3Harris agreed to acquire Aerojet Rocketdyne - the last independent American merchant supplier of rocket propulsion - closing the $4.7 billion deal in July 2023 and making it a fourth business segment at closing (' + a(AERO, 'the completion release') + '). The logic was industrial policy as much as arithmetic: hypersonics, missile defense and the space-launch backlog all bottleneck on propulsion, and the Pentagon wanted a second source strengthened. A later realignment folded propulsion into Missile Solutions, and today the company reports three segments - Space and Mission Systems, Communications and Spectrum Dominance, and Missile Solutions - $21.87 billion of revenue and $1.61 billion of earnings in fiscal 2025, with about 45,000 employees (' + a(STK, 'the current financials') + ').'),
 p(' The portfolio reads like a tour of the infrastructure nobody photographs: missile-warning satellites and their sensors, electronic-warfare suites, the fuzes and proximity sensors inside ordnance, the tactical radios in soldiers\' packs, and - the anomaly in the catalogue - the telephone network of civilian American aviation (' + a(FOX, 'Fox Business') + '). That anomaly is the point of this story. Every other L3Harris product is built to work when someone is trying to break it. The FAA network was built to work when nobody was watching. Friday tested the second assumption.'),
]})

G.append({'heading': '6. Friday', 'blocks': [
 p(' At least one remote FAA site - officials told Reuters the suspect routers may have been at sites in both Arkansas and Texas - was getting the routine treatment on Friday: a contractor crew swapping the old copper line onto fiber, the same operation performed thousands of times across the 150-to-200-path monthly cadence. The router that went in began flooding the network - more than 1,000 connection attempts every four to five seconds, in the Secretary\'s telling - and the flood spread from router to router across the national system until controller communications and radar feeds degraded beyond the FAA\'s tolerance (' + a(DOT, 'the Transportation Department\'s Saturday statement') + '). The FAA stopped departures nationwide for about five hours. Roughly 10,000 flights were cancelled and more than 7,000 delayed; some 3,500 aircraft already aloft were landed safely; the stop lifted around 8:15 PM Eastern, and by Saturday morning the system was back at full operations (' + a(USAT, 'USA Today') + '). "We don\'t believe this was cyber," Duffy said - a provisional assessment, his words, with the investigation still open.'),
 p(' What failed, precisely, is the question the weekend could not answer. "We\'re working to determine whether we had incompetence - meaning was it user error or installer error from L3Harris - or did they install a faulty router? We haven\'t determined what the fault was," Duffy said (' + a(FOX, 'Fox Business') + '). The equipment context matters: this was maintenance on the legacy network - Administrator Bedford described routine work on the old multiplexed-copper plant - not the Peraton-led $12.5 billion modernization, and none of the new fiber equipment went down, Duffy said. The FAA is running additional testing with L3Harris to hunt for further risk. The company, for its part, issued a statement saying it takes the ground stop seriously and is supporting the investigation - and noting, pointedly, that the conversion it was performing when the network failed is the very modernization everyone agrees is overdue (' + a(USAT, 'USA Today') + ').'),
]})

G.append({'heading': '7. The podium', 'blocks': [
 p(' Saturday\'s press conference had a subtext no one bothered to hide. The Secretary needs $50 billion from Congress for a new architecture, and he said the quiet part aloud: "Until I can build that, I\'m stuck with L3Harris, who owns this network" (' + a(FOX, 'Fox Business') + '). Read that sentence twice, because it is the whole strategic position in one clause. The FAA outsourced its nervous system in 2002 to the lowest-risk bidder, and twenty-four years later the government cannot fly a plane without its contractor - a dependency the Secretary simultaneously decried, funded, and blamed. The market read it as contractor risk: L3Harris shares, which had closed Friday quietly up 0.2 percent at $272.35, fell more than 4 percent in after-hours trading once the naming began (' + a(STK, 'the tape') + ').'),
 p(' The decision now sitting on Chris Kubasik\'s desk is not really about a router. If the investigation lands on installer error, L3Harris is the company whose crew broke the National Airspace System; if it lands on a faulty unit, L3Harris is the company that installed it without catching it; either way, the customer that cannot replace it has just told the country it wants to. The playbook for moments like this was written by the company itself, in its own milestone language: build, test in parallel, switch in the dark, never stop the operation. The build story that began with two brothers feeding paper now ends - for this chapter - in a fluorescent-lit network operations center in Melbourne, where the people who run the network America flies on are waiting to learn which of two bad answers belongs to them. What the next chapter holds depends on a September 2027 deadline, a $50 billion ask, and whether the contractor that knows the old network best ends up building the new one - or being written out of it.'),
]})

d = json.load(open('editions-src/longreads.json'))
d['41'] = lr
json.dump(d, open('editions-src/longreads.json','w'), indent=1, ensure_ascii=False)
print('LR41 written:', sum(len(g['blocks']) for g in G), 'blocks,',
      sum(len(b['html'].split()) for g in G for b in g['blocks']), 'words')
